# Forward chaining with explicit negation: a missing fact is not its negation.
facts = {
    ("movie_year", "chihuahua", 2010),
    ("card_color", "ostrich", "indigo"),
    ("occupation", "ostrich", "public_relations_specialist"),
    ("friends", "shark", 16),
    ("invests", "shark", "fangtooth"),
    ("age_soon_years", "shark", 4),
}
rainbow = {"red", "orange", "yellow", "green", "blue", "indigo", "violet"}
facebook_founded = 2004

# Ground rules whose numeric/color antecedents are evaluated exactly.
rules = [
    ({("occupation", "ostrich", "education")},
     ("not_invests", "ostrich", "shark")),
    ({("hides_cards", "chihuahua", "shark"),
      ("not_invests", "ostrich", "shark")},
     ("disarms", "shark", "zebra")),
]
for fact in tuple(facts):
    if fact[0] == "movie_year" and fact[1] == "chihuahua":
        if fact[2] > facebook_founded:
            rules.append(({fact}, ("hides_cards", "chihuahua", "shark")))
    if fact[0] == "card_color" and fact[1] == "ostrich":
        if fact[2] in rainbow:
            rules.append(({fact}, ("not_invests", "ostrich", "shark")))
    if fact[0] == "friends" and fact[1] == "shark":
        if fact[2] > 10:
            rules.append(({fact}, ("acquires_photo", "shark", "swallow")))

animals = {
    "chihuahua", "ostrich", "shark", "fangtooth",
    "badger", "basenji", "zebra", "dugong", "swallow",
}
for animal in animals:
    rules.extend([
        ({("smiles", animal, "basenji"), ("disarms", animal, "zebra")},
         ("not_dances", animal, "dugong")),
        ({("invests", animal, "fangtooth")},
         ("pays", animal, "badger")),
        ({("pays", animal, "badger")},
         ("smiles", animal, "basenji")),
    ])

# Rule 7 has no satisfied antecedent: turning four years old does not
# establish an age below eighteen months. Keep its antecedent explicit.
rules.append((
    {("age_under_months", "shark", 18)},
    ("acquires_photo", "shark", "swallow"),
))

while True:
    additions = {
        consequent
        for antecedents, consequent in rules
        if antecedents <= facts
    } - facts
    if not additions:
        break
    facts.update(additions)

positive = ("dances", "shark", "dugong") in facts
negative = ("not_dances", "shark", "dugong") in facts
if positive and negative:
    result = "inconsistent"
elif positive:
    result = "proved"
elif negative:
    result = "disproved"
else:
    result = "unknown"

for fact in [
    ("hides_cards", "chihuahua", "shark"),
    ("not_invests", "ostrich", "shark"),
    ("disarms", "shark", "zebra"),
    ("pays", "shark", "badger"),
    ("smiles", "shark", "basenji"),
    ("not_dances", "shark", "dugong"),
]:
    print(f"{fact}: {fact in facts}")
print("Expected result:", result)
print("Submitted answer: unknown")
print("CHECK PASS" if result == "unknown" else "CHECK FAIL")
